/* @lc app=leetcode id=1498 lang=kotlin */ class Solution { fun numSubseq(nums: IntArray, target: Int): Int = nums.sorted().let { sorted -> IntArray(sorted.size).also { pow -> pow[0] = 1.also { (1 until sorted.size).forEach { i -> pow[i] = (pow[i - 1] * 2) % 1_000_000_007 } } }.let { pow -> generateSequence((0 to sorted.size - 1) to 0) { (lr, ans) -> lr.let { (l, r) -> if (l <= r) if (sorted[l] + sorted[r] <= target) (l + 1 to r) to ((ans + pow[r - l]) % 1_000_000_007) else (l to r - 1) to ans else null } }.last().second } } }